163:func normalizeRequest(request Request, options Options) Request {
164:	if strings.TrimSpace(request.Root) == "" {
165:		request.Root = options.DefaultRoot
166:	}
167:	if strings.TrimSpace(request.Root) == "" {
168:		request.Root = "."
169:	}
170:	if strings.TrimSpace(request.State) == "" {
171:		request.State = options.DefaultState
172:	}
173:	if request.StateMode == "" {
174:		request.StateMode = options.DefaultMode
175:	}
176:	if request.StateMode == "" {
177:		request.StateMode = repostate.RefreshIfNeeded
178:	}
179:	if request.Mode == "search" && strings.EqualFold(strings.TrimSpace(request.Breadth), "narrow") && strings.TrimSpace(request.Detail) == "" {
180:		request.Detail = "handles"
181:	}
182:	if request.Limit == 0 {
183:		switch {
184:		case request.Mode == "search" && strings.EqualFold(strings.TrimSpace(request.Breadth), "narrow"):
185:			request.Limit = 4
186:		case request.Mode == "trace":
187:			request.Limit = 8
188:		default:
189:			request.Limit = 12
190:		}
191:	}
192:	if strings.TrimSpace(request.LexiconCmd) == "" {
193:		request.LexiconCmd = resolveProviderCommand(request.Root, request.LexiconCmd, "lexicon")
194:	}
195:	if strings.TrimSpace(request.ArcanaCmd) == "" {
196:		request.ArcanaCmd = resolveProviderCommand(request.Root, request.ArcanaCmd, "arcana")
197:	}
198:	return request
199:}
