201:func resolveStatePath(root, state string) (string, error) {
202:	absoluteRoot, err := filepath.Abs(root)
203:	if err != nil {
204:		return "", fmt.Errorf("resolve repository root: %w", err)
205:	}
206:	if strings.TrimSpace(state) == "" {
207:		return filepath.Join(absoluteRoot, ".grimoire"), nil
208:	}
209:	if filepath.IsAbs(state) {
210:		return filepath.Clean(state), nil
211:	}
212:	return filepath.Join(absoluteRoot, state), nil
213:}
