240:func retrieveDocuments(ctx context.Context, request Request, statePath string, preparation repostate.Status, handles []string) ([]knowledge.Result, int, []string, error) {
241:	if !includeDocuments(request) && len(handles) == 0 {
242:		return nil, 0, nil, nil
243:	}
244:	knowledgeState := filepath.Join(statePath, "knowledge")
245:	current, loadErr := knowledge.Load(knowledgeState)
246:	rebuild := loadErr != nil || preparation.Knowledge.Status != "current"
247:	if rebuild {
248:		var previous *knowledge.Index
249:		if loadErr == nil {
250:			previous = &current
251:		} else if !errors.Is(loadErr, os.ErrNotExist) && !errors.Is(loadErr, knowledge.ErrIncompatibleIndex) {
252:			return nil, 0, nil, fmt.Errorf("load knowledge index: %w", loadErr)
253:		}
254:		built, _, err := knowledge.Build(request.Root, previous, knowledge.BuildOptions{})
255:		if err != nil {
256:			return nil, 0, nil, fmt.Errorf("build knowledge index: %w", err)
257:		}
258:		built.SourceFingerprint = preparation.Repository.SourceFingerprint
259:		if err := knowledge.Save(knowledgeState, built); err != nil {
260:			return nil, 0, nil, fmt.Errorf("save knowledge index: %w", err)
261:		}
262:		current = built
263:	}
264:
265:	results := make([]knowledge.Result, 0)
266:	for _, handle := range handles {
267:		value, err := knowledge.Inspect(current, "", handle)
268:		if err != nil {
269:			return nil, 0, nil, err
270:		}
271:		result, ok := value.(knowledge.Result)
272:		if !ok {
273:			return nil, 0, nil, fmt.Errorf("knowledge handle %q did not resolve to a section", handle)
274:		}
275:		results = append(results, result)
276:	}
277:	explicitCount := len(results)
278:	if request.Mode == "inspect" && len(handles) > 0 && strings.TrimSpace(request.Query) == "" {
279:		return results, len(results), nil, nil
280:	}
281:	query := strings.TrimSpace(request.Query)
282:	if query == "" {
283:		query = strings.TrimSpace(request.Anchor)
284:	}
285:	if query == "" && request.Mode == "orient" {
286:		query = "repository architecture overview entry points design rationale"
287:	}
288:	if query == "" {
289:		return results, len(results), nil, nil
290:	}
291:	topK := request.Limit
292:	if topK <= 0 {
293:		if request.Mode == "trace" {
294:			topK = 8
295:		} else {
296:			topK = 12
297:		}
298:	}
299:	if topK > 200 {
300:		topK = 200
301:	}
302:	candidateLimit := min(200, max(topK*4, topK))
303:	searchOptions := knowledge.SearchOptions{TopK: candidateLimit}
304:	if useDocumentVectors(request) && knowledgevector.Available(knowledgeState) {
305:		searchOptions.Vector = knowledgevector.Ranker{State: knowledgeState, Index: current, Endpoint: embedding.DefaultEndpoint}
306:	}
307:	searched, err := knowledge.Search(ctx, current, query, searchOptions)
308:	if err != nil {
309:		return nil, 0, nil, fmt.Errorf("search knowledge: %w", err)
310:	}
311:	compacted := compactKnowledgeResults(searched.Results)
312:	available := uniqueKnowledgeResultCount(results, compacted)
313:	if len(compacted) > topK {
314:		compacted = compacted[:topK]
315:	}
316:	results = appendUniqueKnowledge(results, compacted...)
317:	results = applyKnowledgePreviews(results, explicitCount, request.Detail)
318:	warnings := []string(nil)
319:	if searched.VectorError != "" {
320:		warnings = append(warnings, "knowledge vector ranking unavailable: "+searched.VectorError)
321:	}
322:	return results, available, warnings, nil
323:}
