325:func uniqueKnowledgeResultCount(existing, candidates []knowledge.Result) int {
326:	seen := make(map[string]bool, len(existing)+len(candidates))
327:	for _, result := range existing {
328:		seen[result.Handle] = true
329:	}
330:	for _, result := range candidates {
331:		seen[result.Handle] = true
332:	}
333:	return len(seen)
334:}
335:
336:func compactKnowledgeResults(results []knowledge.Result) []knowledge.Result {
337:	const maxTextBytes = 1200
338:	const maxCodeLinks = 8
339:	const maxReasons = 4
340:	compacted := append([]knowledge.Result(nil), results...)
341:	for index := range compacted {
342:		result := &compacted[index]
343:		result.Text = compactKnowledgeText(result.Text, maxTextBytes)
344:		if len(result.CodeLinks) > maxCodeLinks {
345:			result.CodeLinks = result.CodeLinks[:maxCodeLinks]
346:		}
347:		if len(result.Reasons) > maxReasons {
348:			result.Reasons = result.Reasons[:maxReasons]
349:		}
350:	}
351:	return compacted
352:}
353:
354:func compactKnowledgeText(text string, maxBytes int) string {
355:	text = strings.TrimSpace(text)
356:	if len(text) <= maxBytes {
357:		return text
358:	}
359:	cut := maxBytes
360:	for cut > 0 && !utf8.RuneStart(text[cut]) {
361:		cut--
362:	}
363:	text = strings.TrimSpace(text[:cut])
364:	if boundary := strings.LastIndexAny(text, "\n.!? "); boundary >= maxBytes/2 {
365:		text = strings.TrimSpace(text[:boundary])
366:	}
367:	return text + "…"
368:}
369:
370:func appendUniqueKnowledge(existing []knowledge.Result, values ...knowledge.Result) []knowledge.Result {
371:	seen := make(map[string]bool, len(existing)+len(values))
372:	for _, value := range existing {
373:		seen[value.Handle] = true
374:	}
375:	for _, value := range values {
376:		if !seen[value.Handle] {
377:			seen[value.Handle] = true
378:			existing = append(existing, value)
379:		}
380:	}
381:	return existing
382:}
