200:func perform(ctx context.Context, status *Status, name string, runner CommandRunner, command ProcessCommand) error {
201:	started := now()
202:	action := Action{Name: name, Status: "running"}
203:	status.Actions = append(status.Actions, action)
204:	if runner == nil {
205:		runner = runCommand
206:	}
207:	err := runner(ctx, command)
208:	last := &status.Actions[len(status.Actions)-1]
209:	last.ElapsedMS = elapsedMS(started)
210:	status.Timings.addAction(name, last.ElapsedMS)
211:	if err != nil {
212:		last.Status = "failed"
213:		last.Error = err.Error()
214:		return fmt.Errorf("%s: %w", name, err)
215:	}
216:	last.Status = "completed"
217:	return nil
218:}
