315:func atomicWrite(path string, data []byte) error {
316:	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
317:		return err
318:	}
319:	temporary := fmt.Sprintf("%s.tmp-%d", path, os.Getpid())
320:	if err := os.WriteFile(temporary, data, 0o644); err != nil {
321:		return err
322:	}
323:	if err := os.Rename(temporary, path); err != nil {
324:		_ = os.Remove(temporary)
325:		return err
326:	}
327:	return nil
328:}
