139:	lexiconFacts := flags.String("lexicon-facts", "", "explicit Lexicon JSONL export directory for semantic source spans")
140:	lexiconState := flags.String("lexicon-state", "", "Lexicon state directory; defaults to <root>/.lexicon")
141:	lexiconCommand := flags.String("lexicon-command", "lexicon", "Lexicon executable used for immutable snapshot export")
142:	var excludePaths stringListFlag
143:	flags.Var(&excludePaths, "exclude", "root-relative or absolute path to exclude; may be repeated")
144:	if err := flags.Parse(args); err != nil {
145:		return err
