125:func Load(repository string) (Config, error) {
126:	data, err := os.ReadFile(Path(repository))
127:	if err != nil {
128:		return Config{}, fmt.Errorf("read Lexicon configuration: %w", err)
129:	}
130:	var value Config
131:	if err := json.Unmarshal(data, &value); err != nil {
132:		return Config{}, fmt.Errorf("decode Lexicon configuration: %w", err)
133:	}
134:	if value.Version != Version {
135:		return Config{}, fmt.Errorf("unsupported Lexicon configuration version %d", value.Version)
136:	}
137:	value.EnabledLanguages, err = NormalizeEnabledLanguages(value.EnabledLanguages)
138:	if err != nil {
139:		return Config{}, fmt.Errorf("validate Lexicon enabled languages: %w", err)
140:	}
141:	return value, nil
142:}
