150:func findAdapterRoot(repository, explicit, executable, current string) (string, error) {
151:	candidates := []string{explicit, os.Getenv("LEXICON_ADAPTERS")}
152:	if executable != "" {
153:		executableDir := filepath.Dir(executable)
154:		candidates = append(candidates,
155:			filepath.Join(executableDir, "adapters"),
156:			filepath.Join(executableDir, "..", "adapters"),
157:		)
158:	}
159:	candidates = append(candidates, filepath.Join(repository, "adapters"))
160:	if current != "" {
161:		candidates = append(candidates, filepath.Join(current, "adapters"))
162:	}
163:	for _, candidate := range candidates {
164:		if candidate == "" {
165:			continue
166:		}
167:		absolute, err := filepath.Abs(candidate)
168:		if err != nil {
169:			continue
170:		}
171:		if info, err := os.Stat(filepath.Join(absolute, "python")); err == nil && info.IsDir() {
172:			return absolute, nil
173:		}
174:	}
175:	return "", fmt.Errorf("adapter root not found; use --adapters or LEXICON_ADAPTERS")
176:}
