18:type Options struct {
19:	Debounce  time.Duration
20:	Reconcile time.Duration
21:	Output    io.Writer
22:}
23:
24:func Run(ctx context.Context, scanner *scan.Scanner, options Options) error {
25:	watcher, err := fsnotify.NewWatcher()
26:	if err != nil {
27:		return err
28:	}
29:	defer watcher.Close()
30:	policy, err := lexfiles.LoadIgnorePolicy(scanner.Repository)
31:	if err != nil {
32:		return err
33:	}
34:	if err := addTree(watcher, scanner.Repository, policy); err != nil {
35:		return err
36:	}
37:	if report, err := scanner.Scan(ctx); err != nil {
38:		return err
39:	} else {
40:		writeReport(options.Output, "startup", report)
41:	}
42:	if options.Debounce <= 0 {
43:		options.Debounce = 150 * time.Millisecond
44:	}
45:	if options.Reconcile <= 0 {
46:		options.Reconcile = 30 * time.Second
47:	}
48:	pending := make(map[string]struct{})
49:	fullScan := false
50:	var timer *time.Timer
51:	var timerChannel <-chan time.Time
52:	reconcile := time.NewTicker(options.Reconcile)
53:	defer reconcile.Stop()
54:	for {
55:		select {
56:		case <-ctx.Done():
57:			return nil
58:		case event, ok := <-watcher.Events:
59:			if !ok {
60:				return nil
61:			}
62:			if lexfiles.IsIgnoreFile(scanner.Repository, event.Name) {
63:				policy, err = lexfiles.LoadIgnorePolicy(scanner.Repository)
64:				if err != nil {
65:					return err
66:				}
67:				if err := addTree(watcher, scanner.Repository, policy); err != nil {
68:					return err
69:				}
70:				clear(pending)
71:				fullScan = true
72:				if timer == nil {
73:					timer = time.NewTimer(options.Debounce)
74:				} else if !timer.Stop() {
75:					select {
76:					case <-timer.C:
77:					default:
78:					}
79:				}
80:				timer.Reset(options.Debounce)
81:				timerChannel = timer.C
82:				continue
83:			}
84:			if ignored(policy, event.Name) {
85:				continue
86:			}
87:			if event.Op&fsnotify.Create != 0 {
88:				if info, statErr := os.Stat(event.Name); statErr == nil && info.IsDir() {
89:					_ = addTree(watcher, event.Name, policy)
90:				}
91:			}
92:			if relevantEvent(event) {
93:				pending[event.Name] = struct{}{}
94:				if timer == nil {
95:					timer = time.NewTimer(options.Debounce)
96:				} else if !timer.Stop() {
97:					select {
98:					case <-timer.C:
99:					default:
100:					}
101:				}
102:				timer.Reset(options.Debounce)
103:				timerChannel = timer.C
104:			}
105:		case <-timerChannel:
106:			paths := sortedKeys(pending)
107:			clear(pending)
108:			timerChannel = nil
109:			var report scan.Report
110:			var scanErr error
111:			if fullScan {
112:				fullScan = false
113:				report, scanErr = scanner.Scan(ctx)
114:			} else {
115:				report, scanErr = scanner.ScanPaths(ctx, paths)
116:			}
117:			if scanErr != nil {
118:				fmt.Fprintf(options.Output, "lexicon demon scan failed: %v\n", scanErr)
119:				continue
120:			}
121:			writeReport(options.Output, "watch", report)
122:		case watchErr, ok := <-watcher.Errors:
123:			if !ok {
124:				return nil
125:			}
126:			fmt.Fprintf(options.Output, "lexicon watcher error: %v; reconciling\n", watchErr)
127:			report, scanErr := scanner.Scan(ctx)
128:			if scanErr != nil {
129:				fmt.Fprintf(options.Output, "lexicon reconciliation failed: %v\n", scanErr)
130:			} else {
131:				writeReport(options.Output, "reconcile", report)
132:			}
133:		case <-reconcile.C:
134:			report, scanErr := scanner.Scan(ctx)
135:			if scanErr != nil {
136:				fmt.Fprintf(options.Output, "lexicon reconciliation failed: %v\n", scanErr)
137:			} else {
138:				writeReport(options.Output, "reconcile", report)
139:			}
140:		}
141:	}
142:}
143:
144:func addTree(watcher *fsnotify.Watcher, root string, policy lexfiles.IgnorePolicy) error {
145:	return filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
146:		if walkErr != nil {
147:			return walkErr
148:		}
149:		if !entry.IsDir() {
150:			return nil
151:		}
152:		if path != root && policy.Ignored(path, true) {
153:			return filepath.SkipDir
154:		}
155:		return watcher.Add(path)
156:	})
157:}
158:
159:func ignored(policy lexfiles.IgnorePolicy, path string) bool {
160:	info, err := os.Lstat(path)
161:	return policy.Ignored(path, err == nil && info.IsDir())
162:}
163:
164:func relevantEvent(event fsnotify.Event) bool {
165:	if event.Op&(fsnotify.Remove|fsnotify.Rename) != 0 {
166:		return true
167:	}
168:	if lexfiles.Relevant(event.Name) {
169:		return true
170:	}
171:	info, err := os.Stat(event.Name)
172:	return err == nil && info.IsDir()
173:}
174:
175:func sortedKeys(values map[string]struct{}) []string {
176:	result := make([]string, 0, len(values))
177:	for value := range values {
178:		result = append(result, value)
179:	}
180:	sort.Strings(result)
181:	return result
182:}
183:
184:func writeReport(output io.Writer, source string, report scan.Report) {
185:	if output == nil || len(report.Changed) == 0 {
186:		return
187:	}
188:	fmt.Fprintf(output, "%s scan: %d files, %s\n", source, len(report.Changed), strings.Join(report.Languages, ", "))
189:}
