13:func (s *Scanner) recoverPending() error {
14:	pending, err := s.Store.Pending()
15:	if errors.Is(err, objectstore.ErrNoPendingPublication) {
16:		return nil
17:	}
18:	if err != nil {
19:		return err
20:	}
21:	head := ""
22:	if s.Git.HasHead() {
23:		head, err = s.Git.Head()
24:		if err != nil {
25:			return err
26:		}
27:	}
28:	if pending.CommitRequired && (head == "" || head == pending.BaseStateCommit) {
29:		return s.Store.ClearPending()
30:	}
31:	manifest := pending.Manifest
32:	manifest.StateCommit = head
33:	if _, err := s.Store.Publish(manifest); err != nil {
34:		return fmt.Errorf("recover pending Lexicon publication: %w", err)
35:	}
36:	return s.Store.ClearPending()
37:}
