39:func (s *Scanner) loadManifest() (objectstore.Manifest, error) {
40:	_, manifest, err := s.Store.Current()
41:	if errors.Is(err, objectstore.ErrNoCurrentSnapshot) {
42:		if s.Git.HasHead() && legacyLibraryExists(s.StateRoot) {
43:			head, headErr := s.Git.Head()
44:			if headErr != nil {
45:				return objectstore.Manifest{}, headErr
46:			}
47:			manifest, err = s.Store.BuildManifest(s.StateRoot, head, config.AnalysisID(), s.AdapterRoot)
48:			if err == nil {
49:				if _, err := s.Store.Publish(manifest); err != nil {
50:					return objectstore.Manifest{}, err
51:				}
52:				return manifest, nil
53:			}
54:			// A corrupt legacy materialization is not authoritative. The caller
55:			// removes it and rebuilds the missing languages from source.
56:			return objectstore.Manifest{Version: objectstore.SnapshotVersion}, nil
57:		}
58:		return objectstore.Manifest{Version: objectstore.SnapshotVersion}, nil
59:	}
60:	if err != nil {
61:		return objectstore.Manifest{}, err
62:	}
63:	if s.Git.HasHead() {
64:		head, err := s.Git.Head()
65:		if err != nil {
66:			return objectstore.Manifest{}, err
67:		}
68:		if manifest.StateCommit != head {
69:			if legacyLibraryExists(s.StateRoot) {
70:				migrated, migrateErr := s.Store.BuildManifest(s.StateRoot, head, config.AnalysisID(), s.AdapterRoot)
71:				if migrateErr == nil {
72:					if _, publishErr := s.Store.Publish(migrated); publishErr != nil {
73:						return objectstore.Manifest{}, publishErr
74:					}
75:					return migrated, nil
76:				}
77:			}
78:			return objectstore.Manifest{}, fmt.Errorf(
79:				"Lexicon snapshot state %s does not match private state %s and no recoverable publication exists",
80:				manifest.StateCommit,
81:				head,
82:			)
83:		}
84:	}
85:	return manifest, nil
86:}
