30:func Run(ctx context.Context, repository, stateRoot, snapshotID string, output io.Writer) error {
31:	directory := filepath.Join(stateRoot, "consumers")
32:	entries, err := os.ReadDir(directory)
33:	if os.IsNotExist(err) {
34:		return nil
35:	}
36:	if err != nil {
37:		return fmt.Errorf("read Lexicon consumers: %w", err)
38:	}
39:	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
40:	var failures []error
41:	for _, entry := range entries {
42:		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
43:			continue
44:		}
45:		if err := runOne(ctx, repository, stateRoot, entry.Name(), snapshotID, output); err != nil {
46:			failures = append(failures, fmt.Errorf("Lexicon consumer %s: %w", entry.Name(), err))
47:		}
48:	}
49:	return errors.Join(failures...)
50:}
