73:	if err != nil {
74:		return Definition{}, err
75:	}
76:	var definition Definition
77:	if err := json.Unmarshal(data, &definition); err != nil {
78:		return Definition{}, fmt.Errorf("decode Lexicon consumer %s: %w", path, err)
79:	}
80:	if err := validateDefinition(definition); err != nil {
