86:func invoke(
87:	ctx context.Context,
88:	definition Definition,
89:	repository, stateRoot, snapshotID string,
90:	output io.Writer,
91:) error {
92:	commandContext, cancel := context.WithTimeout(ctx, timeoutFor(definition))
93:	defer cancel()
94:	command := exec.CommandContext(commandContext, definition.Command, definition.Args...)
95:	command.Dir = repository
96:	command.Env = append(os.Environ(),
97:		"LEXICON_REPOSITORY="+repository,
98:		"LEXICON_STATE_ROOT="+stateRoot,
99:		"LEXICON_SNAPSHOT_ID="+snapshotID,
100:	)
101:	var captured bytes.Buffer
102:	command.Stdout = &captured
103:	command.Stderr = &captured
104:	if err := command.Run(); err != nil {
105:		if commandContext.Err() != nil {
106:			return fmt.Errorf("%w: %v: %s", commandContext.Err(), err, strings.TrimSpace(captured.String()))
107:		}
108:		return fmt.Errorf("%w: %s", err, strings.TrimSpace(captured.String()))
109:	}
110:	if output != nil && captured.Len() > 0 {
111:		_, _ = output.Write(captured.Bytes())
112:		if !bytes.HasSuffix(captured.Bytes(), []byte("\n")) {
113:			_, _ = io.WriteString(output, "\n")
114:		}
115:	}
116:	return nil
117:}
