16:pub fn run_sync(command: &SyncCommand) -> Result<String, SyncError> {
17:    let lexicon_root = storage_root(&command.lexicon, ".lexicon");
18:    repository_state::prepare(&command.state, &lexicon_root)?;
19:    let _lock = SyncLock::acquire(&command.state)?;
20:    let current = LexiconSnapshot::current(&lexicon_root)?;
21:    for warning in current.compatibility_warnings() {
22:        eprintln!("arcana sync WARNING: {warning}");
23:    }
24:    fs::create_dir_all(command.state.join("snapshots"))?;
25:
26:    let output = snapshot_directory(&command.state, current.id())?;
27:    let previous_id = read_current(&command.state)?;
28:    let mode = if complete_snapshot(&output, current.id()) {
29:        "existing"
30:    } else {
31:        if output.try_exists()? {
32:            fs::remove_dir_all(&output)?;
33:        }
34:        build_snapshot(
35:            &lexicon_root,
36:            &command.state,
37:            &output,
38:            previous_id.as_deref(),
39:            &current,
40:        )?
41:    };
42:    publish_current(&command.state, current.id())?;
43:    if command.register {
44:        register_consumer(&lexicon_root, &command.state)?;
45:    }
46:    Ok(format!(
47:        "synced Lexicon snapshot {} mode={} registered={} compatibility_warnings={}\n",
48:        current.id(),
49:        mode,
50:        command.register,
51:        current.compatibility_warnings().len()
52:    ))
53:}
54:
55:fn build_snapshot(
56:    lexicon_root: &Path,
57:    state: &Path,
58:    output: &Path,
59:    previous_id: Option<&str>,
60:    current: &LexiconSnapshot,
61:) -> Result<&'static str, SyncError> {
62:    let temp = state.join("snapshots").join(format!(
63:        ".{}.tmp-{}",
64:        current.id().trim_start_matches("sha256:"),
65:        std::process::id()
66:    ));
67:    if temp.try_exists()? {
68:        fs::remove_dir_all(&temp)?;
69:    }
70:    fs::create_dir(&temp)?;
71:    let mode = match write_snapshot(lexicon_root, state, &temp, previous_id, current) {
72:        Ok(mode) => mode,
73:        Err(error) => {
74:            let _ = fs::remove_dir_all(&temp);
75:            return Err(error);
76:        }
77:    };
78:    fs::write(temp.join("lexicon.snapshot"), format!("{}\n", current.id()))?;
79:    if !current.compatibility_warnings().is_empty() {
80:        fs::write(
81:            temp.join("compatibility.warnings"),
82:            current.compatibility_warnings().join("\n") + "\n",
83:        )?;
84:    }
85:    fs::rename(&temp, output)?;
86:    Ok(mode)
87:}
88:
89:fn write_snapshot(
90:    lexicon_root: &Path,
91:    state: &Path,
92:    output: &Path,
93:    previous_id: Option<&str>,
94:    current: &LexiconSnapshot,
95:) -> Result<&'static str, SyncError> {
96:    if let Some(previous_id) = previous_id.filter(|id| *id != current.id()) {
97:        let previous_directory = snapshot_directory(state, previous_id)?;
98:        let previous_manifest = previous_directory.join("repository.manifest");
99:        if previous_manifest.is_file()
100:            && let (Ok(previous_lexicon), Ok(previous_arcana)) = (
101:                LexiconSnapshot::load(lexicon_root, previous_id),
102:                RepositorySnapshot::open(&previous_manifest),
103:            )
104:        {
105:            if current.shared_objects_changed(&previous_lexicon) {
106:                let compiled = compile_repository_facts(current.facts())?;
107:                write_compiled(output, &compiled, current.facts(), "lexicon", current.id())?;
108:                return Ok("rebuild");
109:            }
110:            let changes = current.changed_paths(&previous_lexicon);
111:            let mut changed_paths = changes.added;
112:            changed_paths.extend(changes.changed);
113:            changed_paths.extend(changes.removed);
114:            changed_paths.sort_unstable();
115:            changed_paths.dedup();
116:            if !changed_paths.is_empty() {
117:                let packed_base = previous_arcana.materialize_base_dataset()?;
118:                if let Ok(update) = plan_file_update(
119:                    previous_arcana.facts(),
120:                    current.facts(),
121:                    &changed_paths,
122:                    &packed_base,
123:                ) {
124:                    write_update(output, &previous_arcana, &update, "lexicon", current.id())?;
125:                    return Ok("overlay");
126:                }
127:            }
128:        }
129:    }
130:
131:    let compiled = compile_repository_facts(current.facts())?;
132:    write_compiled(output, &compiled, current.facts(), "lexicon", current.id())?;
133:    Ok("rebuild")
134:}
