181:fn snapshot_directory(state: &Path, id: &str) -> Result<PathBuf, SyncError> {
182:    let digest = id
183:        .strip_prefix("sha256:")
184:        .filter(|digest| {
185:            digest.len() == 64
186:                && digest
187:                    .bytes()
188:                    .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
189:        })
190:        .ok_or_else(|| SyncError::InvalidState(format!("invalid Lexicon snapshot ID {id}")))?;
191:    Ok(state.join("snapshots").join(digest))
192:}
