5:pub fn prepare(state: &Path, lexicon_root: &Path) -> io::Result<()> {
6:    let state = absolute(state)?;
7:    fs::create_dir_all(&state)?;
8:    mark_hidden(&state)?;
9:
10:    let repository = find_repository_root(&state).or_else(|| {
11:        absolute(lexicon_root)
12:            .ok()
13:            .and_then(|path| find_repository_root(&path))
14:    });
15:    let Some(repository) = repository else {
16:        return Ok(());
17:    };
18:    let Ok(relative) = state.strip_prefix(&repository) else {
19:        return Ok(());
20:    };
21:    if let Some(first) = relative.components().next()
22:        && first.as_os_str().to_string_lossy().starts_with('.')
23:    {
24:        let top = repository.join(first.as_os_str());
25:        if top != state {
26:            mark_hidden(&top)?;
27:        }
28:    }
29:    ensure_ignored(&repository, relative)
30:}
31:
32:fn find_repository_root(start: &Path) -> Option<PathBuf> {
33:    start
34:        .ancestors()
35:        .find(|path| path.join(".git").exists())
36:        .map(Path::to_owned)
37:}
38:
39:fn ensure_ignored(repository: &Path, relative: &Path) -> io::Result<()> {
40:    let mut value = relative.to_string_lossy().replace('\\', "/");
41:    value = value.trim_matches('/').to_owned();
42:    if let Some((first, _)) = value.split_once('/')
43:        && first.starts_with('.')
44:    {
45:        value = first.to_owned();
46:    }
47:    let entry = format!("/{value}/");
48:    let path = repository.join(".gitignore");
49:    let data = match fs::read(&path) {
50:        Ok(data) => data,
51:        Err(error) if error.kind() == io::ErrorKind::NotFound => Vec::new(),
52:        Err(error) => return Err(error),
53:    };
54:    let normalized = String::from_utf8_lossy(&data).replace("\r\n", "\n");
55:    if normalized
56:        .lines()
57:        .any(|line| equivalent_ignore(line, &entry))
58:    {
59:        return Ok(());
60:    }
61:
62:    let newline = if data.windows(2).any(|pair| pair == b"\r\n") {
63:        b"\r\n".as_slice()
64:    } else {
65:        b"\n".as_slice()
66:    };
67:    let mut updated = data;
68:    if !updated.is_empty() && !updated.ends_with(b"\n") {
69:        updated.extend_from_slice(newline);
70:    }
71:    updated.extend_from_slice(entry.as_bytes());
72:    updated.extend_from_slice(newline);
73:    fs::write(path, updated)
74:}
75:
76:fn equivalent_ignore(line: &str, entry: &str) -> bool {
77:    let line = line.trim();
78:    if line.is_empty() || line.starts_with('#') || line.starts_with('!') {
79:        return false;
80:    }
81:    let line = line.trim_start_matches('/').trim_end_matches('/');
82:    let entry = entry.trim().trim_start_matches('/').trim_end_matches('/');
83:    line == entry
84:}
