113:	id, err := readCurrent(filepath.Join(location.lexicon, "CURRENT"))
114:	if errors.Is(err, os.ErrNotExist) {
115:		return ComponentStatus{Status: "absent", StaleReasons: []string{"CURRENT is missing"}}
116:	}
117:	if err != nil {
118:		return ComponentStatus{Status: "failed", StaleReasons: []string{err.Error()}}
119:	}
120:	if !validSnapshotID(id) {
121:		return ComponentStatus{Status: "failed", Snapshot: id, StaleReasons: []string{"CURRENT has an invalid snapshot ID"}}
122:	}
123:	if _, err := os.Stat(filepath.Join(location.lexicon, "snapshots", strings.TrimPrefix(id, "sha256:")+".json")); err != nil {
124:		return ComponentStatus{Status: "failed", Snapshot: id, StaleReasons: []string{"current snapshot manifest is missing"}}
125:	}
126:	status := ComponentStatus{Status: "current", Snapshot: id, Prepared: true}
127:	var marker stateMarker
