142:	if errors.Is(err, os.ErrNotExist) {
143:		return ComponentStatus{Status: "absent", Expected: expected, StaleReasons: []string{"CURRENT is missing"}}
144:	}
145:	if err != nil {
146:		return ComponentStatus{Status: "failed", Expected: expected, StaleReasons: []string{err.Error()}}
147:	}
148:	status := ComponentStatus{Status: "current", Snapshot: id, Expected: expected}
149:	if !validSnapshotID(id) {
150:		status.Status = "failed"
151:		status.StaleReasons = append(status.StaleReasons, "CURRENT has an invalid snapshot ID")
152:		return status
153:	}
154:	if expected == "" {
155:		status.Status = "stale"
156:		status.StaleReasons = append(status.StaleReasons, "Lexicon snapshot is unavailable for alignment")
157:	} else if id != expected {
158:		status.Status = "stale"
159:		status.StaleReasons = append(status.StaleReasons, "Arcana snapshot does not match Lexicon CURRENT")
160:	}
161:	directory := filepath.Join(location.arcana, "snapshots", strings.TrimPrefix(id, "sha256:"))
162:	if warningBytes, warningErr := os.ReadFile(filepath.Join(directory, "compatibility.warnings")); warningErr == nil {
163:		for _, warning := range strings.Split(strings.TrimSpace(string(warningBytes)), "\n") {
164:			if warning != "" {
165:				status.Warnings = append(status.Warnings, warning)
166:			}
167:		}
168:	} else if !errors.Is(warningErr, os.ErrNotExist) {
169:		status.Warnings = append(status.Warnings, "read Arcana compatibility warnings: "+warningErr.Error())
170:	}
171:	if !fileExists(filepath.Join(directory, "repository.manifest")) || !fileExists(filepath.Join(directory, "lexicon.snapshot")) {
172:		status.Status = "stale"
173:		status.StaleReasons = append(status.StaleReasons, "Arcana snapshot is incomplete")
174:	} else if value, readErr := readCurrent(filepath.Join(directory, "lexicon.snapshot")); readErr != nil || value != id {
175:		status.Status = "stale"
176:		status.StaleReasons = append(status.StaleReasons, "Arcana lexicon.snapshot does not match CURRENT")
177:	}
178:	status.Prepared = status.Status == "current"
179:	return status
180:}
