268:func inspectArcanaVectors(location paths, arcanaID string) VectorStatus {
269:	if arcanaID == "" || !validSnapshotID(arcanaID) {
270:		return VectorStatus{Status: "missing", Reason: "no current Arcana snapshot"}
271:	}
272:	digest := strings.TrimPrefix(arcanaID, "sha256:")
273:	base := filepath.Join(location.arcana, "vectors", digest, embedding.Identity())
274:	manifestPath := filepath.Join(base, "manifest.json")
275:	status := VectorStatus{Snapshot: arcanaID, Expected: arcanaID}
276:	if !fileExists(manifestPath) {
277:		status.Status = "missing"
278:		status.Reason = "matching vector index is not prepared"
279:		return status
280:	}
281:
282:	repository, err := readArcanaRepositoryIdentity(filepath.Join(location.arcana, "snapshots", digest, "repository.manifest"))
283:	if err != nil {
284:		status.Status = "stale"
285:		status.Reason = "cannot validate current Arcana graph identity: " + err.Error()
286:		return status
287:	}
288:	var manifest arcanaVectorManifest
289:	if err := readJSON(manifestPath, &manifest); err != nil {
290:		status.Status = "stale"
291:		status.Reason = "invalid Arcana vector manifest: " + err.Error()
292:		return status
293:	}
294:	status.Model = manifest.Model
295:	status.Count = manifest.ItemCount
296:	if reason := validateArcanaVectorManifest(manifest, repository); reason != "" {
297:		status.Status = "stale"
298:		status.Reason = reason
299:		return status
300:	}
301:	vectors := filepath.Join(base, manifest.VectorsFile)
302:	info, err := os.Stat(vectors)
303:	if err != nil || info.IsDir() {
304:		status.Status = "stale"
305:		status.Reason = "Arcana vector data file is missing"
306:		return status
307:	}
308:	status.Bytes = info.Size()
309:	expectedBytes := int64(manifest.ItemCount) * int64(manifest.Dimensions) * 4
310:	if info.Size() != expectedBytes {
311:		status.Status = "stale"
312:		status.Reason = fmt.Sprintf("Arcana vector data is %d bytes; expected %d", info.Size(), expectedBytes)
313:		return status
314:	}
315:	if count, err := countArcanaVectorRecords(filepath.Join(base, manifest.RecordsFile)); err != nil || count != manifest.ItemCount {
316:		status.Status = "stale"
317:		if err != nil {
318:			status.Reason = "invalid Arcana vector node records: " + err.Error()
319:		} else {
320:			status.Reason = fmt.Sprintf("Arcana vector index has %d node records; expected %d", count, manifest.ItemCount)
321:		}
322:		return status
323:	}
324:	for _, data := range []struct {
325:		file, expected, label string
326:	}{
327:		{manifest.RecordsFile, manifest.RecordsSHA256, "node records"},
328:		{manifest.VectorsFile, manifest.VectorsSHA256, "vectors"},
329:	} {
330:		actual, err := fileSHA256(filepath.Join(base, data.file))
331:		if err != nil || actual != data.expected {
332:			status.Status = "stale"
333:			status.Reason = "Arcana vector " + data.label + " checksum does not match its manifest"
334:			return status
335:		}
336:	}
337:	status.Status = "current"
338:	return status
339:}
