361:func readArcanaRepositoryIdentity(path string) (arcanaRepositoryIdentity, error) {
362:	data, err := os.ReadFile(path)
363:	if err != nil {
364:		return arcanaRepositoryIdentity{}, err
365:	}
366:	values := make(map[string]string)
367:	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
368:		name, value, found := strings.Cut(strings.TrimSpace(line), "=")
369:		if found {
370:			values[name] = value
371:		}
372:	}
373:	nodeCount, err := strconv.Atoi(values["node_count"])
374:	if err != nil || nodeCount < 0 || values["version"] != "1" || !validArcanaHexID(values["snapshot_id"]) || !validArcanaHexID(values["graph_snapshot_id"]) {
375:		return arcanaRepositoryIdentity{}, errors.New("repository.manifest has invalid vector identity fields")
376:	}
377:	return arcanaRepositoryIdentity{
378:		SnapshotID: values["snapshot_id"], GraphSnapshotID: values["graph_snapshot_id"],
379:	}, nil
380:}
