389:func validateArcanaVectorManifest(manifest arcanaVectorManifest, repository arcanaRepositoryIdentity) string {
390:	const maxVectorItems = int64(^uint64(0)>>1) / int64(embedding.Dimensions*4)
391:	switch {
392:	case manifest.Version != 3:
393:		return fmt.Sprintf("unsupported Arcana vector index version %d", manifest.Version)
394:	case manifest.RepositorySnapshotID != repository.SnapshotID || manifest.GraphSnapshotID != repository.GraphSnapshotID:
395:		return "Arcana vector index does not match the current graph identity"
396:	case manifest.Model != embedding.ModelReference || manifest.Identity != arcanaSemanticIndexIdentity() || manifest.Dimensions != embedding.Dimensions:
397:		return "Arcana vector index does not match Grimoire's embedding contract"
398:	case manifest.EligibilityPolicyVersion != arcanaSemanticEligibilityPolicyVersion:
399:		return "Arcana vector index does not match the semantic eligibility policy"
400:	case manifest.ItemCount < 0:
401:		return "Arcana vector index has a negative document count"
402:	case int64(manifest.ItemCount) > maxVectorItems:
403:		return "Arcana vector index byte length overflows the supported size"
404:	case manifest.RecordsFile != "nodes.jsonl" || manifest.VectorsFile != "vectors.f32":
405:		return "Arcana vector index uses unsupported data filenames"
406:	case !validSHA256(manifest.RecordsSHA256) || !validSHA256(manifest.VectorsSHA256):
407:		return "Arcana vector index has invalid data checksums"
408:	default:
409:		return ""
410:	}
411:}
