413:func countArcanaVectorRecords(path string) (int, error) {
414:	file, err := os.Open(path)
415:	if err != nil {
416:		return 0, err
417:	}
418:	defer file.Close()
419:	scanner := bufio.NewScanner(file)
420:	count := 0
421:	for scanner.Scan() {
422:		var record struct {
423:			NodeKey string `json:"node_key"`
424:			Kind    string `json:"kind"`
425:			Name    string `json:"name"`
426:		}
427:		if err := json.Unmarshal(scanner.Bytes(), &record); err != nil || !validArcanaHexID(record.NodeKey) || strings.TrimSpace(record.Kind) == "" || strings.TrimSpace(record.Name) == "" {
428:			if err != nil {
429:				return 0, err
430:			}
431:			return 0, errors.New("node record has invalid required fields")
432:		}
433:		count++
434:	}
435:	return count, scanner.Err()
436:}
