462:func fileSHA256(path string) (string, error) {
463:	file, err := os.Open(path)
464:	if err != nil {
465:		return "", err
466:	}
467:	defer file.Close()
468:	hash := sha256.New()
469:	if _, err := io.Copy(hash, file); err != nil {
470:		return "", err
471:	}
472:	return fmt.Sprintf("%x", hash.Sum(nil)), nil
473:}
