15:type fileGuard struct{ path string }
16:
17:func acquireFileLock(ctx context.Context, path string) (fileGuard, error) {
18:	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
19:		return fileGuard{}, err
20:	}
21:	for {
22:		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
23:		if err == nil {
24:			_, _ = fmt.Fprintf(file, "pid=%d\ncreated=%s\n", os.Getpid(), time.Now().UTC().Format(time.RFC3339Nano))
25:			_ = file.Close()
26:			return fileGuard{path: path}, nil
27:		}
28:		if !os.IsExist(err) {
29:			return fileGuard{}, err
30:		}
31:		if staleRefreshLock(path) {
32:			if removeErr := os.Remove(path); removeErr == nil || os.IsNotExist(removeErr) {
33:				continue
34:			}
35:		}
36:		timer := time.NewTimer(25 * time.Millisecond)
37:		select {
38:		case <-ctx.Done():
39:			timer.Stop()
40:			return fileGuard{}, ctx.Err()
41:		case <-timer.C:
42:		}
43:	}
44:}
45:
46:func staleRefreshLock(path string) bool {
47:	pid, ok := refreshLockPID(path)
48:	if ok {
49:		return !processAlive(pid)
50:	}
51:	info, err := os.Stat(path)
52:	return err == nil && time.Since(info.ModTime()) > 10*time.Minute
53:}
54:
55:func refreshLockPID(path string) (int, bool) {
56:	file, err := os.Open(path)
57:	if err != nil {
58:		return 0, false
59:	}
60:	defer file.Close()
61:	scanner := bufio.NewScanner(file)
62:	for scanner.Scan() {
63:		value := strings.TrimSpace(scanner.Text())
64:		if raw, ok := strings.CutPrefix(value, "pid="); ok {
65:			pid, err := strconv.Atoi(raw)
66:			return pid, err == nil && pid > 0
67:		}
68:	}
69:	return 0, false
70:}
