18:func runMCP(args []string, input io.Reader, output, stderr io.Writer) error {
19:	flags := flag.NewFlagSet("mcp", flag.ContinueOnError)
20:	flags.SetOutput(stderr)
21:	root := flags.String("root", ".", "default repository root")
22:	state := flags.String("state", "", "default Grimoire state directory")
23:	stateMode := flags.String("state-mode", string(repostate.RefreshIfNeeded), "current-only, refresh-if-needed, or force-refresh")
24:	maxMessage := flags.Int("max-message", 10<<20, "maximum MCP request bytes")
25:	maxInFlight := flags.Int("max-in-flight", 8, "maximum accepted MCP tool calls awaiting completion")
26:	auditLog := flags.String("audit-log", "", "optional private JSONL log of MCP requests and structured responses")
27:	auditIncludeContent := flags.Bool("audit-include-content", false, "include source excerpts in the MCP audit log")
28:	if err := flags.Parse(args); err != nil {
29:		return err
30:	}
31:	if flags.NArg() != 0 {
32:		return fmt.Errorf("unexpected mcp arguments: %s", strings.Join(flags.Args(), " "))
33:	}
34:	mode := repostate.Mode(*stateMode)
35:	switch mode {
36:	case repostate.CurrentOnly, repostate.RefreshIfNeeded, repostate.ForceRefresh:
37:	default:
38:		return errors.New("--state-mode must be current-only, refresh-if-needed, or force-refresh")
39:	}
40:	if *maxMessage <= 0 {
41:		return errors.New("positive --max-message is required")
42:	}
43:	if *maxInFlight <= 0 {
44:		return errors.New("positive --max-in-flight is required")
45:	}
46:	if *auditIncludeContent && strings.TrimSpace(*auditLog) == "" {
47:		return errors.New("--audit-include-content requires --audit-log")
48:	}
49:
50:	audit := newMCPAuditLogger(*auditLog, *auditIncludeContent)
51:	queryRuntime := agentquery.NewRuntime()
52:	defer queryRuntime.Close()
53:	handler := mcpserver.HandlerFunc(func(ctx context.Context, arguments json.RawMessage) (any, error) {
54:		var request agentruntime.Request
55:		if err := json.Unmarshal(arguments, &request); err != nil {
56:			return nil, fmt.Errorf("decode Grimoire agent request: %w", err)
57:		}
58:		response, executeErr := agentruntime.Execute(ctx, request, agentruntime.Options{
59:			DefaultRoot:      *root,
60:			DefaultState:     *state,
61:			DefaultMode:      mode,
62:			EnsureRepository: ensureDiscoveryRepository,
63:			ExecuteQuery:     queryRuntime.Execute,
64:		})
65:		return response, audit.Record(request, response, executeErr)
66:	})
67:	server, err := mcpserver.New(mcpserver.Options{
68:		Name:         "grimoire",
69:		Version:      Version,
70:		ToolName:     "grimoire_discover",
71:		Description:  "Discover repository evidence through independent exact-source, source, documentation, and symbol lanes, then explicitly trace, assess impact, or inspect stable handles.",
72:		Instructions: "Before calling Grimoire, use direct search and file reads when an exact path or symbol is already known. Use breadth=narrow for localized ownership or impact questions; it returns handle-only discovery by default, so inspect selected handles before expanding. Use balanced only for distributed or unclear context. Stop once the owner, controlling behavior, public boundary, and relevant tests are established. Follow trace or impact only for a named unresolved relationship. Reuse one session name to deduplicate repeated evidence.",
73:		InputSchema:  agentToolInputSchema(),
74:		MaxMessage:   *maxMessage,
75:		MaxInFlight:  *maxInFlight,
76:	}, handler)
77:	if err != nil {
78:		return err
79:	}
80:	return server.Serve(context.Background(), input, output)
81:}
