57:	case "eval":
58:		if len(args) > 1 && args[1] == "arcana" {
59:			return runEvalArcana(args[2:], stdout, stderr)
60:		}
61:		if len(args) > 1 && args[1] == "knowledge" {
62:			return runEvalKnowledge(args[2:], stdout, stderr)
63:		}
64:		return errors.New("expected evaluation command: arcana or knowledge")
65:	case "model":
66:		return runModel(args[1:], stdout, stderr)
67:	case "vector":
68:		return runKnowledgeVector(args[1:], stdout, stderr)
69:	case "investigation":
