131:func runIndex(args []string, stdout, stderr io.Writer) error {
132:	flags := flag.NewFlagSet("index", flag.ContinueOnError)
133:	flags.SetOutput(stderr)
134:	root := flags.String("root", ".", "repository root")
135:	state := flags.String("state", "", "prepared index repository path")
136:	ignoreFile := flags.String("ignore-file", "", "root-relative or absolute ignore file; defaults to .gitignore hierarchy")
137:	maxFileBytes := flags.Int64("max-file-bytes", 0, "maximum indexed file size")
138:	includeGenerated := flags.Bool("include-generated", false, "include generated, vendored, lock, bundled, and minified content")
139:	lexiconFacts := flags.String("lexicon-facts", "", "explicit Lexicon JSONL export directory for semantic source spans")
140:	lexiconState := flags.String("lexicon-state", "", "Lexicon state directory; defaults to <root>/.lexicon")
141:	lexiconCommand := flags.String("lexicon-command", "lexicon", "Lexicon executable used for immutable snapshot export")
142:	var excludePaths stringListFlag
143:	flags.Var(&excludePaths, "exclude", "root-relative or absolute path to exclude; may be repeated")
144:	if err := flags.Parse(args); err != nil {
145:		return err
146:	}
147:
148:	statePath, err := resolveState(*root, *state)
149:	if err != nil {
150:		return err
151:	}
152:	if err := repostatefs.Prepare(*root, statePath); err != nil {
153:		return err
154:	}
155:	previous, err := loadOptional(statePath)
156:	if err != nil {
157:		return err
158:	}
159:
160:	sourceSpans, lexiconSnapshot, spanErr := resolveIndexSourceSpans(
161:		*root, statePath, *lexiconFacts, *lexiconState, *lexiconCommand,
162:	)
163:	if spanErr != nil {
164:		if strings.TrimSpace(*lexiconFacts) != "" || strings.TrimSpace(*lexiconState) != "" {
165:			return fmt.Errorf("resolve Lexicon semantic spans: %w", spanErr)
166:		}
167:		_, _ = fmt.Fprintf(stderr, "warning: Lexicon semantic spans unavailable; using line-window chunking: %v\n", spanErr)
168:	}
169:
170:	excluded := append([]string{statePath}, excludePaths...)
171:	snapshot, stats, err := index.Build(*root, previous, index.BuildOptions{
172:		MaxFileBytes:     *maxFileBytes,
173:		IgnoreFile:       *ignoreFile,
174:		ExcludePaths:     excluded,
175:		IncludeGenerated: *includeGenerated,
176:		SourceSpans:      sourceSpans,
177:	})
178:	if err != nil {
179:		return err
180:	}
181:	if err := index.Save(statePath, snapshot); err != nil {
182:		return err
183:	}
184:
185:	chunking := "fallback"
186:	if stats.SemanticFiles > 0 {
187:		chunking = "lexicon"
188:	}
189:	response := struct {
190:		State           string           `json:"state"`
191:		Files           int              `json:"files"`
192:		Chunking        string           `json:"chunking"`
193:		LexiconSnapshot string           `json:"lexicon_snapshot,omitempty"`
194:		Stats           index.BuildStats `json:"stats"`
195:	}{
196:		State: statePath, Files: len(snapshot.Files), Chunking: chunking,
197:		LexiconSnapshot: lexiconSnapshot, Stats: stats,
198:	}
199:	return writeJSON(stdout, response)
200:}
201:
202:func resolveState(root, state string) (string, error) {
203:	absoluteRoot, err := filepath.Abs(root)
204:	if err != nil {
205:		return "", fmt.Errorf("resolve root: %w", err)
206:	}
207:	if state == "" {
208:		state = strings.TrimSpace(os.Getenv("GRIMOIRE_STATE_DIR"))
209:		if state == "" {
210:			return filepath.Join(absoluteRoot, ".grimoire"), nil
211:		}
212:	}
213:	if filepath.IsAbs(state) {
214:		return filepath.Clean(state), nil
215:	}
216:	return filepath.Join(absoluteRoot, state), nil
217:}
218:
219:func loadOptional(path string) (*index.Snapshot, error) {
220:	snapshot, err := index.Load(path)
221:	if errors.Is(err, os.ErrNotExist) {
222:		return nil, nil
223:	}
224:	if errors.Is(err, index.ErrIncompatibleIndex) {
225:		base, rebuildErr := index.RebuildBase(path)
226:		if rebuildErr != nil {
227:			return nil, fmt.Errorf("prepare index rebuild: %w", rebuildErr)
228:		}
229:		return &base, nil
230:	}
231:	if err != nil {
232:		return nil, fmt.Errorf("load existing index: %w", err)
233:	}
234:	return &snapshot, nil
235:}
