78:
79:func NormalizeEnabledLanguages(enabledLanguages []string) ([]string, error) {
80:	supported := make(map[string]struct{}, len(languageRegistry.Supported()))
81:	for _, language := range languageRegistry.Supported() {
82:		supported[language] = struct{}{}
83:	}
84:	set := make(map[string]struct{}, len(enabledLanguages))
85:	for _, language := range enabledLanguages {
86:		if _, ok := supported[language]; !ok {
87:			return nil, fmt.Errorf("unsupported Lexicon language %q", language)
88:		}
89:		set[language] = struct{}{}
90:	}
91:	normalized := make([]string, 0, len(set))
92:	for language := range set {
93:		normalized = append(normalized, language)
94:	}
95:	sort.Strings(normalized)
96:	return normalized, nil
97:}
