99:func (value Config) LanguageEnabled(language string) bool {
100:	if _, supported := languageRegistry.Lookup(language); !supported {
101:		return false
102:	}
103:	if len(value.EnabledLanguages) == 0 {
104:		return true
105:	}
106:	for _, enabled := range value.EnabledLanguages {
107:		if enabled == language || (enabled == "generic" && languageRegistry.IsGeneric(language)) {
108:			return true
109:		}
110:	}
111:	return false
112:}
