22:		return 2
23:	}
24:	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
25:	defer stop()
26:	var err error
27:	switch arguments[0] {
28:	case "init":
29:		err = runInit(ctx, arguments[1:], stdout, stderr)
30:	case "scan":
31:		err = runScan(ctx, arguments[1:], stdout, stderr)
32:	case "demon":
33:		err = runDemon(ctx, arguments[1:], stdout, stderr)
34:	case "rebuild":
35:		err = runRebuild(ctx, arguments[1:], stdout, stderr)
36:	case "export":
37:		err = runExport(arguments[1:], stdout, stderr)
38:	case "gc":
39:		err = runGC(arguments[1:], stdout, stderr)
40:	case "languages":
41:		err = runLanguages(ctx, arguments[1:], stdout, stderr)
42:	case "consumer":
43:		err = runConsumer(ctx, arguments[1:], stdout, stderr)
44:	case "status":
45:		err = runStatus(arguments[1:], stdout, stderr)
46:	case "doctor":
47:		err = runDoctor(arguments[1:], stdout, stderr)
48:	case "version":
49:		err = runVersion(stdout)
50:	case "help", "-h", "--help":
51:		usage(stdout)
52:		return 0
53:	default:
54:		fmt.Fprintf(stderr, "unknown command %q\n", arguments[0])
55:		usage(stderr)
56:		return 2
57:	}
58:	if err != nil {
59:		fmt.Fprintln(stderr, err)
60:		return 1
61:	}
62:	return 0
63:}
