55:func (s *Scanner) scan(ctx context.Context, synchronize func() error) (Report, error) {
56:	guard, err := lock.Acquire(s.Store.Root)
57:	if err != nil {
58:		return Report{}, err
59:	}
60:	defer guard.Close()
61:	if err := s.recoverPending(); err != nil {
62:		return Report{}, err
63:	}
64:	if err := s.Git.ResetIndex(); err != nil {
65:		return Report{}, err
66:	}
67:	manifest, err := s.loadManifest()
68:	if err != nil {
69:		return Report{}, err
70:	}
71:	legacyRemoved, err := s.removeLegacyLibrary()
72:	if err != nil {
73:		return Report{}, err
74:	}
75:	if err := synchronize(); err != nil {
76:		return Report{}, err
77:	}
78:	if err := s.Git.StageSource(); err != nil {
79:		return Report{}, err
80:	}
81:	changes, err := s.Git.SourceChanges()
82:	if err != nil {
83:		return Report{}, err
84:	}
85:	manifest, pruned := s.pruneDisabledLanguages(manifest)
86:	drift, err := snapshotDriftLanguages(s.StateRoot, manifest, s.languageEnabled)
87:	if err != nil {
88:		return Report{}, err
89:	}
90:	adapterDrift, err := s.adapterDriftLanguages(manifest)
91:	if err != nil {
92:		return Report{}, err
93:	}
94:	drift = mergeLanguages(drift, adapterDrift)
95:	plans, err := s.plansFor(changes, drift)
96:	if err != nil {
97:		return Report{}, err
98:	}
99:	interstackDrift := interstackDrifted(manifest)
100:	if len(changes) == 0 && len(plans) == 0 && !pruned && !legacyRemoved && !interstackDrift {
101:		snapshotID, err := s.ensureSnapshot(manifest)
102:		return Report{SnapshotID: snapshotID}, err
103:	}
104:	manifest, err = s.analyzePlans(ctx, manifest, plans)
105:	if err != nil {
106:		return Report{}, err
107:	}
108:	manifest, err = s.refreshInterstack(manifest)
109:	if err != nil {
110:		return Report{}, err
111:	}
112:	snapshotID, err := s.commitManifest(manifest)
113:	if err != nil {
114:		return Report{}, err
115:	}
116:	return Report{Changed: changes, Languages: planLanguages(plans), SnapshotID: snapshotID}, nil
117:}
