12:var ErrBusy = errors.New("Lexicon repository is already being updated")
13:
14:type Lock struct {
15:	file *flock.Flock
16:}
17:
18:func Acquire(root string) (*Lock, error) {
19:	if err := os.MkdirAll(root, 0o755); err != nil {
20:		return nil, fmt.Errorf("create Lexicon state directory: %w", err)
21:	}
22:	file := flock.New(filepath.Join(root, "LOCK"))
23:	locked, err := file.TryLock()
24:	if err != nil {
25:		return nil, fmt.Errorf("acquire Lexicon update lock: %w", err)
26:	}
27:	if !locked {
28:		return nil, ErrBusy
29:	}
30:	return &Lock{file: file}, nil
31:}
32:
33:func (l *Lock) Close() error {
34:	if l == nil || l.file == nil {
35:		return nil
36:	}
37:	if err := l.file.Unlock(); err != nil {
38:		return fmt.Errorf("release Lexicon update lock: %w", err)
39:	}
40:	return nil
41:}
