1:use std::fs::{self, File, OpenOptions};
2:use std::io::{self, Write};
3:use std::path::Path;
4:
5:use atomicwrites::replace_atomic;
6:use fs2::FileExt;
7:
8:pub struct SyncLock {
9:    file: File,
10:}
11:
12:impl SyncLock {
13:    pub fn acquire(state: &Path) -> io::Result<Self> {
14:        let file = OpenOptions::new()
15:            .read(true)
16:            .write(true)
17:            .create(true)
18:            .truncate(false)
19:            .open(state.join("LOCK"))?;
20:        file.try_lock_exclusive().map_err(|error| {
21:            io::Error::new(error.kind(), format!("Arcana state is busy: {error}"))
22:        })?;
23:        Ok(Self { file })
24:    }
25:}
26:
27:impl Drop for SyncLock {
28:    fn drop(&mut self) {
29:        let _ = FileExt::unlock(&self.file);
30:    }
31:}
32:
33:pub fn replace_file(path: &Path, bytes: &[u8]) -> io::Result<()> {
34:    let temp = path.with_extension(format!("tmp-{}", std::process::id()));
35:    let result = (|| {
36:        let mut file = OpenOptions::new()
37:            .write(true)
38:            .create_new(true)
39:            .open(&temp)?;
40:        file.write_all(bytes)?;
41:        file.sync_all()?;
42:        drop(file);
43:        replace_atomic(&temp, path)
44:    })();
45:    if result.is_err() {
46:        let _ = fs::remove_file(&temp);
47:    }
48:    result
49:}
