39:func Build(root string, previous *Snapshot, options BuildOptions) (Snapshot, BuildStats, error) {
40:	absoluteRoot, err := filepath.Abs(root)
41:	if err != nil {
42:		return Snapshot{}, BuildStats{}, fmt.Errorf("resolve root: %w", err)
43:	}
44:
45:	maxBytes := options.MaxFileBytes
46:	if maxBytes <= 0 {
47:		maxBytes = defaultMaxFileBytes
48:	}
49:	ignorePolicy, err := ignorepolicy.Load(absoluteRoot, options.IgnoreFile)
50:	if err != nil {
51:		return Snapshot{}, BuildStats{}, err
52:	}
53:	excludedPaths, err := normalizeExcludedPaths(absoluteRoot, options.ExcludePaths)
54:	if err != nil {
55:		return Snapshot{}, BuildStats{}, err
56:	}
57:
58:	oldFiles := make(map[string]FileRecord)
59:	baseRoot := ""
60:	baseShards := make(map[string]string)
61:	if previous != nil {
62:		baseRoot = previous.baseRoot
63:		for name, hash := range previous.baseShards {
64:			baseShards[name] = hash
65:		}
66:		for _, file := range previous.Files {
67:			oldFiles[file.Path] = file
68:		}
69:	}
70:	dirtyShards := make(map[string]bool)
71:	spansByPath := sourceSpansByPath(options.SourceSpans)
72:
73:	seen := make(map[string]struct{})
74:	files := make([]FileRecord, 0, len(oldFiles))
75:	stats := BuildStats{}
76:
77:	err = filepath.WalkDir(absoluteRoot, func(path string, entry fs.DirEntry, walkErr error) error {
78:		if walkErr != nil {
79:			return walkErr
80:		}
81:		if path != absoluteRoot && (permanentlyIgnoredDirectory(entry) || pathExcluded(path, excludedPaths)) {
82:			if entry.IsDir() {
83:				return filepath.SkipDir
84:			}
85:			return nil
86:		}
87:		if path != absoluteRoot && !options.IncludeGenerated && generatedDirectory(entry) {
88:			stats.GeneratedSkipped++
89:			return filepath.SkipDir
90:		}
91:		if path != absoluteRoot {
92:			ignored, err := ignorePolicy.Ignored(path, entry.IsDir())
93:			if err != nil {
94:				return err
95:			}
96:			if ignored {
97:				if entry.IsDir() {
98:					return filepath.SkipDir
99:				}
100:				return nil
101:			}
102:		}
103:		if entry.IsDir() {
104:			return ignorePolicy.LoadDirectory(path)
105:		}
106:		if path == ignorePolicy.ControlFile() || !entry.Type().IsRegular() || !indexableFile(entry.Name()) {
107:			return nil
108:		}
109:		if !options.IncludeGenerated && generatedFileName(entry.Name()) {
110:			stats.GeneratedSkipped++
111:			return nil
112:		}
113:
114:		info, err := entry.Info()
115:		if err != nil {
116:			return err
117:		}
118:		if info.Size() > maxBytes {
119:			return nil
120:		}
121:
122:		content, err := os.ReadFile(path)
123:		if err != nil {
124:			return err
125:		}
126:		if bytes.IndexByte(content, 0) >= 0 {
127:			return nil
128:		}
129:		if !options.IncludeGenerated && generatedFileContent(entry.Name(), content) {
130:			stats.GeneratedSkipped++
131:			return nil
132:		}
133:
134:		relative, err := filepath.Rel(absoluteRoot, path)
135:		if err != nil {
136:			return err
137:		}
138:		relative = filepath.ToSlash(relative)
139:		seen[relative] = struct{}{}
140:		stats.Scanned++
141:
142:		hash := contentHash(content)
143:		fileSpans := spansByPath[relative]
144:		preparationHash := chunkPreparationHash(relative, fileSpans)
145:		if old, ok := oldFiles[relative]; ok && old.Hash == hash && old.Size == info.Size() &&
146:			old.PreparationHash == preparationHash {
147:			files = append(files, old)
148:			stats.Reused++
149:			if semantic := semanticChunkCount(old.Chunks); semantic > 0 {
150:				stats.SemanticFiles++
151:				stats.SemanticChunks += semantic
152:			}
153:			return nil
154:		}
155:
156:		chunks, err := chunkFileWithSourceSpans(relative, string(content), fileSpans)
157:		if err != nil {
158:			return fmt.Errorf("tokenize %s: %w", relative, err)
159:		}
160:		files = append(files, FileRecord{
161:			Path:            relative,
162:			Hash:            hash,
163:			PreparationHash: preparationHash,
164:			Size:            info.Size(),
165:			Chunks:          chunks,
166:		})
167:		if semantic := semanticChunkCount(chunks); semantic > 0 {
168:			stats.SemanticFiles++
169:			stats.SemanticChunks += semantic
170:		}
171:		dirtyShards[shardName(relative)] = true
172:		stats.Updated++
173:		return nil
174:	})
175:	if err != nil {
176:		return Snapshot{}, BuildStats{}, fmt.Errorf("walk repository: %w", err)
177:	}
178:
179:	for path := range oldFiles {
180:		if _, ok := seen[path]; !ok {
181:			dirtyShards[shardName(path)] = true
182:			stats.Removed++
183:		}
184:	}
185:	sort.Slice(files, func(i, j int) bool { return files[i].Path < files[j].Path })
186:
187:	snapshot := Snapshot{
188:		Version: FormatVersion, Tokenizer: tokenizer.Name, Files: files,
189:		baseRoot: baseRoot, baseShards: baseShards, dirtyShards: dirtyShards,
190:	}
191:	var previousLexical *lexical.Index
192:	if previous != nil {
193:		previousLexical = previous.lexicalIndex
194:	}
195:	snapshot.lexicalIndex = buildLexicalIndex(files, previousLexical)
196:	return snapshot, stats, nil
197:}
