199:func indexableFile(name string) bool {
200:	extension := strings.ToLower(filepath.Ext(name))
201:	switch extension {
202:	case ".go", ".rs", ".py", ".rb", ".js", ".jsx", ".ts", ".tsx",
203:		".java", ".c", ".h", ".cc", ".cpp", ".hpp", ".cs", ".gd",
204:		".md", ".txt", ".toml", ".yaml", ".yml", ".json", ".xml",
205:		".html", ".css", ".scss", ".sql", ".sh", ".ps1":
206:		return true
207:	}
208:
209:	switch strings.ToLower(name) {
210:	case "readme", "license", "makefile", "dockerfile", "gemfile", "rakefile":
211:		return true
212:	default:
213:		return false
214:	}
215:}
