127:func gitSourcePaths(root string) ([]string, bool) {
128:	command := exec.Command("git", "-C", root, "ls-files", "-z", "--cached", "--others", "--exclude-standard")
129:	data, err := command.Output()
130:	if err != nil {
131:		return nil, false
132:	}
133:	seen := make(map[string]bool)
134:	paths := make([]string, 0, 256)
135:	for _, raw := range strings.Split(string(data), "\x00") {
136:		relative := filepath.ToSlash(strings.TrimSpace(raw))
137:		if relative == "" || !fingerprintPath(relative) || seen[relative] {
138:			continue
139:		}
140:		seen[relative] = true
141:		paths = append(paths, relative)
142:	}
143:	return paths, true
144:}
