146:func walkedSourcePaths(root string) ([]string, error) {
147:	paths := make([]string, 0, 256)
148:	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
149:		if walkErr != nil {
150:			return walkErr
151:		}
152:		if path != root && entry.IsDir() && excludedDirectory(entry.Name()) {
153:			return filepath.SkipDir
154:		}
155:		if path == root || entry.IsDir() || entry.Type()&os.ModeSymlink != 0 || !entry.Type().IsRegular() {
156:			return nil
157:		}
158:		relative, err := filepath.Rel(root, path)
159:		if err != nil {
160:			return err
161:		}
162:		relative = filepath.ToSlash(relative)
163:		if fingerprintPath(relative) {
164:			paths = append(paths, relative)
165:		}
166:		return nil
167:	})
168:	return paths, err
169:}
