171:func fingerprintPath(relative string) bool {
172:	for _, part := range strings.Split(filepath.ToSlash(relative), "/") {
173:		if excludedDirectory(part) {
174:			return false
175:		}
176:	}
177:	name := strings.ToLower(filepath.Base(relative))
178:	extension := strings.ToLower(filepath.Ext(name))
179:	// This is intentionally a conservative superset of Grimoire-indexed files
180:	// and every source/config input currently consumed by Lexicon. False positives
181:	// may cause an extra refresh; false negatives can leave Arcana on a stale graph.
182:	switch extension {
183:	case ".go", ".rs", ".py", ".rb", ".gemspec", ".js", ".jsx", ".mjs", ".cjs", ".ts", ".tsx", ".mts", ".cts", ".svelte",
184:		".java", ".kt", ".kts", ".c", ".cc", ".cp", ".cpp", ".cxx", ".c++", ".h", ".hh", ".hpp", ".hxx", ".h++", ".inc", ".inl", ".ipp", ".tpp", ".cs", ".gd",
185:		".ls", ".lsa", ".lsdb", ".lss",
186:		".md", ".txt", ".toml", ".yaml", ".yml", ".json", ".xml", ".html", ".css", ".scss",
187:		".mod", ".sum", ".sln", ".csproj", ".props", ".targets", ".gradle", ".cfg", ".godot",
188:		".asm", ".bash", ".bat", ".clj", ".cljs", ".cmd", ".cr", ".dart", ".elm", ".erl", ".ex", ".exs", ".f03", ".f90", ".f95", ".fish", ".fs", ".fsx", ".groovy", ".hs", ".jl", ".lhs", ".lua", ".m", ".ml", ".mli", ".mm", ".nim", ".nims", ".pas", ".php", ".pl", ".pm", ".proto", ".ps1", ".r", ".scala", ".sc", ".s", ".sh", ".sol", ".sql", ".swift", ".sv", ".v", ".vb", ".vbs", ".vim", ".zig":
189:		return true
190:	}
191:	switch name {
192:	case ".gitignore", ".lexiconignore", "readme", "license", "makefile", "dockerfile", "gemfile", "gemfile.lock", "rakefile",
193:		"gradlew", "mvnw", "cargo.lock", "directory.build.props", "directory.build.targets":
194:		return true
195:	default:
196:		return false
197:	}
198:}
