200:func gitRepositoryStatus(ctx context.Context, root string) (head string, dirty, available bool) {
201:	command := exec.CommandContext(ctx, "git", "-C", root, "status", "--porcelain=v2", "-z", "--branch", "--untracked-files=normal", "--ignore-submodules=all")
202:	data, err := command.Output()
203:	if err != nil {
204:		return "", false, false
205:	}
206:	available = true
207:	for _, raw := range strings.Split(string(data), "\x00") {
208:		record := strings.TrimSpace(raw)
209:		if record == "" {
210:			continue
211:		}
212:		if value, ok := strings.CutPrefix(record, "# branch.oid "); ok {
213:			value = strings.TrimSpace(value)
214:			if value != "(initial)" {
215:				head = value
216:			}
217:			continue
218:		}
219:		if strings.HasPrefix(record, "# ") || excludedPorcelainRecord(record) {
220:			continue
221:		}
222:		dirty = true
223:	}
224:	return head, dirty, available
225:}
