125:		return nil
126:	})
127:	if err != nil {
128:		return Index{}, BuildStats{}, fmt.Errorf("walk knowledge documents: %w", err)
129:	}
130:	for path := range old {
131:		if _, ok := seen[path]; !ok {
132:			stats.Removed++
133:		}
134:	}
135:	catalog, catalogErr := buildCodeCatalog(absolute, options.IgnoreFile, excluded)
136:	if catalogErr != nil {
