148:func isKnowledgeFile(path, name string, includeConfig bool) bool {
149:	lower := strings.ToLower(path)
150:	ext := strings.ToLower(filepath.Ext(name))
151:	if ext == ".md" || ext == ".mdx" || ext == ".markdown" || ext == ".adoc" || ext == ".rst" || ext == ".txt" {
152:		return true
153:	}
154:	base := strings.ToLower(filepath.Base(path))
155:	if ext == "" && (strings.Contains(base, "readme") || strings.Contains(base, "changelog") || strings.Contains(base, "notes") || strings.Contains(base, "design")) {
156:		return true
157:	}
158:	if looksKnowledgePath(lower) && (ext == ".json" || ext == ".yaml" || ext == ".yml" || ext == ".toml" || ext == ".ini" || ext == ".conf") {
159:		return includeConfig || proseHeavyConfig(path)
160:	}

182:func inspectGrimoire(location paths, fingerprint, lexiconID string) ComponentStatus {
183:	status := ComponentStatus{Status: "absent"}
184:	snapshot, err := index.Load(location.grimoire)
185:	if err != nil {
186:		if !errors.Is(err, os.ErrNotExist) {
187:			status.Status = "failed"
188:			status.StaleReasons = []string{err.Error()}
189:			return status
190:		}
191:		status.StaleReasons = []string{"prepared index is missing"}
192:		return status
193:	}
194:	status.Status = "current"
195:	status.Snapshot = snapshot.Identity()
196:	status.Prepared = true
197:	var marker stateMarker
198:	if err := readJSON(filepath.Join(location.grimoire, ".repostate.json"), &marker); err != nil {
199:		status.Status = "stale"
200:		status.Prepared = false
201:		status.StaleReasons = append(status.StaleReasons, "preparation metadata is missing")
202:		return status
203:	}
204:	if marker.SourceFingerprint != fingerprint {
205:		status.Status = "stale"
206:		status.Prepared = false
207:		status.StaleReasons = append(status.StaleReasons, "source fingerprint changed since Grimoire preparation")
208:	}
209:	if marker.LexiconSnapshot != lexiconID {
210:		status.Status = "stale"
211:		status.Prepared = false
212:		status.StaleReasons = append(status.StaleReasons, "prepared index Lexicon snapshot is not current")
213:	}
214:	return status
215:}
