217:func inspectKnowledge(location paths, repositoryFingerprint string) (ComponentStatus, knowledge.Index, bool) {
218:	stored, err := knowledge.Load(location.knowledge)
219:	if errors.Is(err, os.ErrNotExist) {
220:		return ComponentStatus{Status: "absent", StaleReasons: []string{"knowledge index is missing"}}, knowledge.Index{}, false
221:	}
222:	if err != nil {
223:		return ComponentStatus{Status: "failed", StaleReasons: []string{err.Error()}}, knowledge.Index{}, false
224:	}
225:	actual := knowledge.Identity(stored)
226:	status := ComponentStatus{Status: "current", Snapshot: actual, Expected: actual, Prepared: true}
227:	if stored.SourceFingerprint == "" {
228:		status.Status = "stale"
229:		status.Prepared = false
230:		status.StaleReasons = append(status.StaleReasons, "knowledge freshness metadata is missing")
231:	} else if stored.SourceFingerprint != repositoryFingerprint {
232:		status.Status = "stale"
233:		status.Prepared = false
234:		status.StaleReasons = append(status.StaleReasons, "repository content changed since knowledge indexing")
235:	}
236:	return status, stored, true
237:}
