123:func (s *Scanner) pruneDisabledLanguages(manifest objectstore.Manifest) (objectstore.Manifest, bool) {
124:	pruned := false
125:	for _, entry := range append([]objectstore.LanguageEntry(nil), manifest.Languages...) {
126:		if entry.Language == "interstack" || s.languageEnabled(entry.Language) {
