88:func (s *Scanner) commitManifest(manifest objectstore.Manifest) (string, error) {
89:	if err := s.Git.StageAll(); err != nil {
90:		return "", err
91:	}
92:	baseHead := ""
93:	if s.Git.HasHead() {
94:		var err error
95:		baseHead, err = s.Git.Head()
96:		if err != nil {
97:			return "", err
98:		}
99:	}
100:	commitRequired := !s.Git.HasHead() || s.Git.HasStagedChanges()
101:	if err := s.Store.WritePending(baseHead, commitRequired, manifest); err != nil {
102:		return "", err
103:	}
104:	if err := s.Git.CommitState(); err != nil {
105:		return "", err
106:	}
107:	head, err := s.Git.Head()
108:	if err != nil {
109:		return "", err
110:	}
111:	manifest.StateCommit = head
112:	id, err := s.Store.Publish(manifest)
113:	if err != nil {
114:		return "", err
115:	}
116:	if err := s.Store.ClearPending(); err != nil {
117:		return "", err
118:	}
119:	return id, nil
120:}
